def rewrite_calls(text, name, fn):
    pattern=re.compile(r'\b'+re.escape(name)+r'\s*\(')
    pos=0
    while True:
        m=pattern.search(text,pos)
        if not m: break
        opening=text.index('(',m.start()); depth=1; i=opening+1; start=i; args=[]
        while depth:
            ch=text[i]
            if ch=='(': depth+=1
            elif ch==')': depth-=1
            elif ch==',' and depth==1: args.append(text[start:i].strip());start=i+1
            i+=1
        if text[start:i-1].strip():args.append(text[start:i-1].strip())
        new=fn(args); text=text[:m.start()]+new+text[i:];pos=m.start()+len(new)
    return text

def source_identity(symbol):
    return 'UINT32_C(0x'+format(IDENTITIES[symbol],'08x')+')'

def transform(unit,source):
    life=unit['domain']=='lifecycle'; ctx='isle_cave_lifecycle' if life else 'isle_cave_actor'
    S='IsleCaveLifecycleSource' if life else 'IsleCaveActorSource'
    original=source; name=unit['symbol']; factory=unit['role'] in ['factory6','factory5','void_factory5']
    # POKEMON_FUNC expands only the proven local native semantic borrows.
    source=re.sub(r'POKEMON_FUNC\('+re.escape(name)+r'\)', 'void '+name+'(GObj* obj) {\n    DObj* model = obj->data.dobj;\n    Mtx3Float* position = &GET_TRANSFORM(model)->pos;\n    Mtx4Float* rotation = &GET_TRANSFORM(model)->rot;\n    Pokemon* pokemon = GET_POKEMON(obj);', source)
    brace=source.index('{');sig=source[:brace].strip();body=source[brace+1:source.rfind('}')]
