    body=re.sub(r'\\\s*\n','\n',body)
    body=re.sub(r'(?m)^[ \t]*UNUSED s32 pad\[\d+\];[ \t]*(?:\n|$)','\n',body)
    if unit['role']=='animation':
        callback_type='IsleActorNodeRef' if life else 'IsleGameModelRef'
        sig='void '+name+'('+S+'* s, const '+callback_type+'* callback_model, int32_t '+unit['event_name']+', float '+unit['value_name']+')'
        for var in ['arg0','dobj']:
            if var==unit['model_name']:body=re.sub(r'\b'+var+r'\b','(*callback_model)',body)
    elif unit['role']=='model_utility':
        sig='void '+name+'(IsleCaveActorSource* s, IsleGameModelRef transform, float arg1)'
    elif factory:
        if unit['role']!='factory6': body='\n    IsleCaveActorSource* s = isle_cave_actor_factory_require('+unit['block_name']+', '+unit['reference_name']+', spawn);'+body
        sig=sig.replace('WorldBlock*','IsleActorFactoryBlock*')
    elif unit['role']=='callback' or 'GObj*' in sig:
        receiver=unit['receiver'];body='\n    '+S+'* s = '+ctx+'_require('+receiver+'->game, '+receiver+');'+body
    else:
        params=sig[sig.index('(')+1:sig.rfind(')')].strip()
        params='' if params=='void' else ', '+params
        sig=sig[:sig.index('(')+1]+S+'* s'+params+')'


    if life:
        body=body.replace('WorldBlock*','IsleCaveWorldBlock*')
        for symbol in ['D_80317610_699AC0','D_80317618_699AC8']: body=body.replace('&'+symbol,source_identity(symbol))
        body=body.replace('arg0->next', 'isle_cave_lifecycle_block_next(s, arg0)')
        for var in ['arg0','next']:
            for axis in 'xyz':body=body.replace(var+'->descriptor->worldPos.'+axis,'isle_cave_lifecycle_block_position(s, '+var+').'+axis)
        for asset,enum in [('fx_script_common','ISLE_CAVE_FX_SCRIPT_COMMON'),('fx_img_common','ISLE_CAVE_FX_IMAGES_COMMON'),('fx_script_cave','ISLE_CAVE_FX_SCRIPT_CAVE'),('fx_img_cave','ISLE_CAVE_FX_IMAGES_CAVE')]:
            body=body.replace('func_800A73C0((u32) '+asset+'_ROM_START, (u32) '+asset+'_ROM_END)', 'isle_cave_lifecycle_asset_load(s, '+enum+')')
        body=body.replace('void* scriptDesc;','IsleCaveLifecycleAsset* scriptDesc;').replace('void* spritesDesc;','IsleCaveLifecycleAsset* spritesDesc;')
        body=body.replace('D_80382D10_523120 = func_800A2094(4, 100, getMainCamera());','isle_cave_lifecycle_fx_manager_assign(s, func_800A2094(4, 100, getMainCamera()));')
        body=body.replace('D_80382D14_523124 = fx_allocEffects(10);','isle_cave_lifecycle_fx_pool_assign(s, fx_allocEffects(10));')
        body=body.replace('D_802C637C_64882C.zBuffer','s->screen.depth_buffer').replace('&D_802C637C_64882C','&s->screen')
        body=body.replace('ARRAY_COUNT(fx_SpriteBanksNum)','8').replace('fx_ScriptBanksNum[i] = fx_SpriteBanksNum[i] = 0;','isle_cave_lifecycle_fx_reset_bank(s, i);')
        body=body.replace('r << 0x18 | g << 0x10 | b << 8', '(uint32_t)r << 24 | (uint32_t)g << 16 | (uint32_t)b << 8')
        body=body.replace('getMainCamera()->flags |= CAMERA_FLAG_2;','isle_cave_lifecycle_camera_flags(s, 2u, 2u);')
        body=body.replace('&D_802C6150_648600','s->environment')
        body=body.replace('*((s32*) &D_8033E138_6C05E8) = 0;', 'memset(&D_8033E138_6C05E8, 0, sizeof(D_8033E138_6C05E8));')
        body=body.replace('D_802C6398_648848.gtlSetup.heapSize = (uintptr_t) cave_code_VRAM - (uintptr_t) cave_assets_VRAM_END;','s->scene_setup.heap_size = UINT32_C(0x10ef10);')
        body=body.replace('omSetupScene(&D_802C6398_648848);','isle_cave_lifecycle_setup_scene(s, &s->scene_setup);')
        for fn,se in [('pokemonAdd','pokemon_add'),('pokemonsChangeBlock','pokemon_change'),('pokemonRemove','pokemon_remove')]:
            body=rewrite_calls(body,fn,lambda a,se=se:'isle_cave_lifecycle_'+se+'(s, '+', '.join(a[:-1])+', s->definitions, 18)')
        body=rewrite_calls(body,'createWorld',lambda a:'isle_cave_lifecycle_world_create(s, '+source_identity('D_8012A0E8')+', '+', '.join(a[1:])+')')
        for fn,se in LIFE_CALLS.items():body=rewrite_calls(body,fn,lambda a,se=se:'isle_cave_lifecycle_'+se+'(s'+(', '+', '.join(a) if a else '')+')')

    # Every direct caller follows explicitly injected helper context.
    for helper in CONTEXT_HELPERS:
        body=rewrite_calls(body,helper,lambda a,h=helper:h+'(s'+(', '+', '.join(a) if a else '')+')')
    body=body.replace('temp_v1 = (PokemonTransform*) pokemon->interactionTarget->userData;','temp_v1 = '+ctx+'_item_collision_velocity(s, pokemon->interactionTarget);')
    body=body.replace('PokemonTransform* temp_v1;','IsleGameVec3 temp_v1;').replace('temp_v1->rot.a','temp_v1.x').replace('temp_v1->rot.v.y','temp_v1.z')
    # Preserve pointer-through-word provenance with native retained path storage.
    body=body.replace('pokemon->miscVars[2].field1 = (s32) pokemon->path;',ctx+'_path_save(s, obj, pokemon->path);')
    body=body.replace('pokemon->path = (InterpData*) pokemon->miscVars[2].field1;','pokemon->path = '+ctx+'_path_restore(s, obj);')
    body=re.sub(r'pokemon->path->paramPoints\[(\d+)\]',lambda m:ctx+'_path_point(s, pokemon->path, '+m[1]+')',body)

